    auto start = clock();
    for (int it = 0; it < 100000000; ++it) {
        foo(s);
    }
    std::cout << "foo(string) took " << (clock() - start) << " cycles" << std::endl;

    start = clock();
    for (int it = 0; it < 100000000; ++it) {
        bar(s);
    }
