    start = clock();
    for (int it = 0; it < 100000000; ++it) {
        foo("blockhash");
    }
    std::cout << "foo(\"string literal\") took " << (clock() - start) << " cycles" << std::endl;

    start = clock();
    for (int it = 0; it < 100000000; ++it) {
        bar("blockhash");
    }
