Code review e6c02b9f2544032481743b4f8d3148622ccc73dd
 I think this PR as of e6c02b9f2544032481743b4f8d3148622ccc73dd has been good exploration of possible changes, but is doing too much and is too complicated. I think it's worth starting with a minimal change that just supports `std::span` and `std::byte` in CScript and replaces `_hex_v_u8` with `_hex`:

<details><summary>diff</summary>
<p>

```diff
--- a/src/script/script.h
+++ b/src/script/script.h
@@ -463,7 +463,7 @@ public:
         return *this;
     }
 
-    CScript& operator<<(const std::vector<unsigned char>& b) LIFETIMEBOUND
+    CScript& operator<<(std::span<const std::byte> b) LIFETIMEBOUND
     {
         if (b.size() < OP_PUSHDATA1)
         {
@@ -488,10 +488,17 @@ public:
             WriteLE32(_data, b.size());
             insert(end(), _data, _data + sizeof(_data));
         }
-        insert(end(), b.begin(), b.end());
+        const value_type* _data{reinterpret_cast<const value_type*>(b.data())};
+        insert(end(), _data, _data + b.size());
         return *this;
     }
 
+    // For backwards compatibility. Please prefer std::byte over uint8_t in new code.
+    CScript& operator<<(std::span<const uint8_t> b) LIFETIMEBOUND
+    {
+        return *this << std::as_bytes(b);
+    }
+
     bool GetOp(const_iterator& pc, opcodetype& opcodeRet, std::vector<unsigned char>& vchRet) const
     {
         return GetScriptOp(pc, end(), opcodeRet, &vchRet);
