Suggestion 1: we swap the state machine when encountering a `%`, otherwise inc the param count and step out of the format:
```C++
constexpr static void CheckNumFormatSpecifiers(std::string_view str)
{
    int count{0};
    bool in_format{false};
    for (char c : str) {
        if (c == '%') in_format = !in_format;
        else if (in_format) {
            ++count;
            in_format = false;
        }
    }
    if (num_params != count) throw std::runtime_error("Format specifier count must match the argument count!");
 }
```

----

Suggestion 2: count the excesses and throw when there is any:
```C++
constexpr static void CheckNumFormatSpecifiers(std::string_view str)
{
    int excess{num_params};
    bool in_format{false};
    for (char c : str) {
        if (c == '%') in_format = !in_format;
        else if (in_format) {
            --excess;
            in_format = false;
        }
    }
    if (excess) throw std::runtime_error("Format specifier count must match the argument count!");
 }
``` if we'd throw a `runtime_error`, testing would become slightly more reasonable:
```C++
std::runtime_error("Format specifier count must match the argument count!")
